import {cacheKey} from './cache.mjs';
export function runSequence(ids, joint=false) {
 const state={cache:new Map(),legacy:!joint};
 for(const id of ids) {
  if(id==='enable')state.legacy=true;
  else if(id==='blue')state.cache.set(cacheKey('blue','7'),'blue:7');
  else if(id==='reset')state.cache.clear();
  else if(id==='setup-error')return 'unrelated-failure';
  else if(id!=='noise')throw Error('unknown predecessor');
 }
 const value=state.legacy ? state.cache.get(cacheKey('red','7')) ?? 'red:7' : 'red:7';
 return value==='red:7'?'clean':'target-symptom';
}
